<template>
  <section class="space-y-4">
    <div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-sm font-semibold">员工祝福贺卡</h2><p class="mt-1 text-xs text-muted-foreground">制作图片或 HTML 贺卡，可预览、分享链接，或发给指定员工。</p></div><div class="flex gap-2"><Button variant="outline" size="sm" :disabled="loading || busy" @click="load">刷新</Button><Button size="sm" @click="openCreate"><Plus />制作贺卡</Button></div></div>
    <Callout v-if="error" tone="destructive" title="贺卡加载失败">{{ error }}</Callout><p v-else-if="loading" class="text-sm text-muted-foreground">正在读取贺卡…</p><EmptyState v-else-if="!cards.length" title="还没有制作贺卡" description="为生日、入职周年或其他值得纪念的时刻送上祝福。" :icon="Cake" class="panel"><Button size="sm" @click="openCreate"><Plus />制作第一张贺卡</Button></EmptyState>
    <div v-else class="grid gap-3 md:grid-cols-2 xl:grid-cols-3"><article v-for="card in cards" :key="card.id" class="panel flex flex-col p-4"><div class="flex items-center gap-2"><span class="grid size-9 place-items-center rounded-lg bg-primary/10 text-primary"><Cake v-if="card.kind === 'birthday'" class="size-4" /><Heart v-else class="size-4" /></span><div class="min-w-0 flex-1"><p class="truncate text-sm font-semibold">{{ card.recipientName }}</p><p class="mt-0.5 text-xs text-muted-foreground">{{ kindLabel(card.kind) }}{{ card.years ? ` · ${card.years} 周年` : '' }}</p></div><Badge variant="secondary">{{ card.format === 'image' ? '图片' : 'HTML' }}</Badge></div><h3 class="mt-4 break-words text-sm font-medium">{{ card.title }}</h3><p class="mt-2 line-clamp-3 flex-1 whitespace-pre-wrap text-xs leading-6 text-muted-foreground">{{ card.message }}</p><p class="mt-3 text-[11px] text-muted-foreground">{{ formatPortalDateTime(card.createdAt) }}</p><p v-if="card.errorMsg" class="mt-2 break-words text-xs text-destructive">{{ card.errorMsg }}</p><Badge v-if="card.sentAt" class="mt-2 self-start" :variant="flag(card.sentOk) ? 'success' : 'destructive'">{{ flag(card.sentOk) ? '链接已发送' : '发送失败' }}</Badge><div class="mt-3 flex flex-wrap items-center justify-between gap-1 border-t pt-3"><Button variant="outline" size="sm" :disabled="busy" @click="preview(card)">预览 / 分享</Button><Button variant="ghost" size="sm" :disabled="busy || !card.userId" :title="card.userId ? '向绑定员工发送贺卡链接' : '该贺卡未绑定在职员工，可复制链接分享'" @click="pending = card">{{ card.sentAt ? '重新发送链接' : '发送贺卡链接' }}</Button></div></article></div>
    <Pagination :page="page" :page-size="12" :total="total" @update:page="page = $event; load()" />
    <Dialog :open="createOpen" title="制作员工祝福贺卡" size="lg" @update:open="!busy && (createOpen = $event)">
      <form id="celebration-card-form" class="space-y-4" @submit.prevent="create"><Callout v-if="formError" tone="destructive">{{ formError }}</Callout><div class="grid gap-4 sm:grid-cols-2"><div><label for="card-recipient" class="field-label">绑定员工</label><Select id="card-recipient" v-model="form.userId" :options="[{ value: null, label: '仅制作，手动填写收件人' }, ...employees.map(e => ({ value: e.userId, label: `${e.name} · ${e.department || e.username}` }))]" @update:model-value="recipientChanged" /></div><div><label for="card-recipient-name" class="field-label">贺卡上的收件人名称 *</label><Input id="card-recipient-name" v-model="form.recipientName" :readonly="!!form.userId" required maxlength="100" /></div><div><label for="card-kind" class="field-label">贺卡类型</label><Select id="card-kind" v-model="form.kind" :options="[{ value: 'birthday', label: '生日' }, { value: 'anniversary', label: '入职周年' }, { value: 'custom', label: '自定义' }]" /></div><div><label for="card-format" class="field-label">贺卡形式</label><Select id="card-format" v-model="form.format" :options="[{ value: 'image', label: '图片贺卡' }, { value: 'html', label: 'HTML 贺卡' }]" /></div><div v-if="form.kind === 'anniversary'" class="sm:col-span-2"><label for="card-years" class="field-label">入职周年数</label><Input id="card-years" v-model="form.years" type="number" min="1" max="100" step="1" /></div></div><div><label for="card-title" class="field-label">祝福标题 *</label><Input id="card-title" v-model="form.title" required maxlength="100" /></div><div><label for="card-message" class="field-label">祝福正文 *</label><Textarea id="card-message" v-model="form.message" required maxlength="500" :rows="5" /><p class="mt-1 text-right text-[11px] text-muted-foreground">{{ form.message.length }} / 500</p></div><div><label for="card-avatar" class="field-label">收件人照片</label><Input id="card-avatar" :key="avatarKey" type="file" accept=".png,.jpg,.jpeg" :disabled="busy" @change="selectAvatar" /><div v-if="form.avatarData" class="mt-2 flex items-center gap-3"><img :src="form.avatarData" alt="贺卡照片预览" class="size-16 rounded-full object-cover" /><Button size="sm" variant="ghost" @click="form.avatarData = ''; avatarKey++">移除照片</Button></div><p class="mt-1 text-xs text-muted-foreground">可选，支持 PNG 或 JPG，最大 2MB。</p></div><Checkbox v-model="form.send" :disabled="!form.userId">制作后立即向绑定员工发送贺卡链接</Checkbox><p class="text-xs text-muted-foreground">未勾选发送时仅生成贺卡，之后可在列表中预览并分享。</p></form>
      <template #footer><Button variant="outline" :disabled="busy" @click="createOpen = false">取消</Button><Button type="submit" form="celebration-card-form" :loading="busy">{{ form.send ? '制作并发送贺卡链接' : '生成贺卡' }}</Button></template>
    </Dialog>
    <Dialog :open="!!previewCard" :title="previewCard?.title ?? '贺卡预览'" size="lg" @update:open="!$event && closePreview()">
      <div v-if="previewCard" class="space-y-4"><p v-if="previewLoading" class="text-sm text-muted-foreground">正在生成预览…</p><Callout v-if="previewError" tone="destructive">{{ previewError }}</Callout><img v-if="previewCard.format === 'image' && previewUrl" :src="previewUrl" :alt="`${previewCard.recipientName}的祝福贺卡`" class="mx-auto w-full rounded-lg border" /><iframe v-else-if="safeMediaUrl(previewCard.url)" :src="safeMediaUrl(previewCard.url)" title="HTML 贺卡预览" sandbox="" referrerpolicy="no-referrer" class="h-[55dvh] w-full rounded-lg border bg-white" /><div><label for="card-share-url" class="field-label">贺卡分享链接</label><div class="flex gap-2"><Input id="card-share-url" :model-value="safeMediaUrl(previewCard.url) ?? ''" readonly @focus="($event.target as HTMLInputElement).select()" /><Button variant="outline" @click="copyLink(previewCard)"><Copy />复制</Button></div><p class="mt-1 text-xs text-muted-foreground">拥有此链接的人可查看贺卡，请按需分享。</p></div></div>
      <template #footer><Button v-if="previewCard?.format === 'image'" variant="outline" :disabled="!previewBlob" @click="downloadImage"><Download />下载图片</Button><Button variant="outline" @click="closePreview">关闭</Button></template>
    </Dialog>
    <ConfirmDialog :open="!!pending" title="发送贺卡链接" :description="`通过企业微信向「${pending?.recipientName ?? ''}」发送这张贺卡的链接？`" :busy="busy" @update:open="!busy && !$event && (pending = null)" @confirm="send" />
  </section>
</template>
<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import { Cake, Copy, Download, Heart, Plus } from '@lucide/vue'
import { api } from '../../lib/api'
import { portalFile, savePortalFile } from '../../lib/portal-files'
import { safeMediaUrl } from '../../lib/portal-training'
import { errText, toast } from '../../lib/toast'
import Badge from '../../ui/Badge.vue'
import Button from '../../ui/Button.vue'
import Callout from '../../ui/Callout.vue'
import Checkbox from '../../ui/Checkbox.vue'
import ConfirmDialog from '../../ui/ConfirmDialog.vue'
import Dialog from '../../ui/Dialog.vue'
import EmptyState from '../../ui/EmptyState.vue'
import Input from '../../ui/Input.vue'
import Pagination from '../../ui/Pagination.vue'
import Select from '../../ui/Select.vue'
import Textarea from '../../ui/Textarea.vue'
import { formatPortalDateTime } from '../../lib/portal-management-format'
interface Card { id: number; userId?: number | null; token: string; kind: string; recipientName: string; title: string; message: string; years?: number; format: string; sentOk: boolean | number; errorMsg?: string; createdAt: string; sentAt?: string; url: string; imageUrl: string }
const props = defineProps<{ employees: { userId: number; name: string; department?: string; username: string }[] }>()
const emit = defineEmits<{ sent: [] }>()
const base = '/admin-api/portal/celebrations', cards = ref<Card[]>([]), page = ref(1), total = ref(0), loading = ref(false), busy = ref(false), error = ref(''), createOpen = ref(false), formError = ref(''), avatarKey = ref(0)
const form = reactive({ userId: null as number | null, recipientName: '', kind: 'birthday', title: '生日快乐！', message: '愿你每一天都有新的收获与快乐，祝福你！', years: '', format: 'image', send: false, avatarData: '' })
const pending = ref<Card | null>(null), previewCard = ref<Card | null>(null), previewLoading = ref(false), previewError = ref(''), previewUrl = ref(''), previewBlob = ref<Blob | null>(null)
let loadSeq = 0, previewSeq = 0
const flag = (value: boolean | number) => value === true || value === 1
const kindLabel = (kind: string) => ({ birthday: '生日贺卡', anniversary: '入职周年', custom: '自定义祝福' } as Record<string, string>)[kind] ?? kind
async function load() { const seq = ++loadSeq; loading.value = true; error.value = ''; try { const data = await api.get<{ list: Card[]; total: number }>(`${base}/cards`, { pageNo: page.value, pageSize: 12 }); if (seq === loadSeq) { cards.value = data.list; total.value = data.total } } catch (e) { if (seq === loadSeq) error.value = errText(e) } finally { if (seq === loadSeq) loading.value = false } }
function openCreate() { Object.assign(form, { userId: null, recipientName: '', kind: 'birthday', title: '生日快乐！', message: '愿你每一天都有新的收获与快乐，祝福你！', years: '', format: 'image', send: false, avatarData: '' }); avatarKey.value++; formError.value = ''; createOpen.value = true }
function recipientChanged() { const employee = props.employees.find(e => e.userId === form.userId); if (employee) form.recipientName = employee.name; if (!form.userId) form.send = false }
async function selectAvatar(event: Event) { const input = event.target as HTMLInputElement, file = input.files?.[0]; if (!file) return; if (!/\.(png|jpe?g)$/i.test(file.name) || !file.size || file.size > 2 * 1024 * 1024) { formError.value = '照片须为不超过 2MB 的 PNG 或 JPG'; input.value = ''; return } try { form.avatarData = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error('照片读取失败')); reader.readAsDataURL(file) }); formError.value = '' } catch { formError.value = '照片读取失败，请重新选择' } }
async function create() { if (busy.value) return; busy.value = true; formError.value = ''; try { const result = await api.post<Card>(`${base}/cards`, { userId: form.userId ?? undefined, recipientName: form.recipientName.trim(), kind: form.kind, title: form.title.trim(), message: form.message.trim(), years: form.kind === 'anniversary' && form.years ? Number(form.years) : undefined, format: form.format, send: form.send, avatarData: form.avatarData || undefined }, 90000); createOpen.value = false; await load(); await preview(result); if (form.send && !flag(result.sentOk)) toast(result.errorMsg || '贺卡已生成，链接发送失败，可从列表重试', 'bad'); else toast(form.send ? '贺卡链接已提交企业微信' : '贺卡已生成'); if (form.send) emit('sent') } catch (e) { formError.value = errText(e) } finally { busy.value = false } }
async function preview(card: Card) { closePreview(); const seq = ++previewSeq; previewCard.value = card; previewError.value = ''; if (card.format !== 'image') return; previewLoading.value = true; try { const data = await portalFile(`${base}/cards/${card.id}/image`); if (seq === previewSeq) { previewBlob.value = data.blob; previewUrl.value = URL.createObjectURL(data.blob) } } catch (e) { if (seq === previewSeq) previewError.value = errText(e) } finally { if (seq === previewSeq) previewLoading.value = false } }
function closePreview() { previewSeq++; previewCard.value = null; previewBlob.value = null; previewLoading.value = false; if (previewUrl.value) URL.revokeObjectURL(previewUrl.value); previewUrl.value = '' }
function downloadImage() { if (previewBlob.value) savePortalFile(previewBlob.value, `${previewCard.value?.recipientName ?? '员工'}-祝福贺卡.jpg`) }
async function copyLink(card: Card) { const url = safeMediaUrl(card.url); if (!url) { toast('分享链接不可用', 'bad'); return } try { await navigator.clipboard.writeText(url); toast('贺卡链接已复制') } catch { toast('复制失败，请从地址框中手动复制', 'bad') } }
async function send() { if (!pending.value || busy.value) return; busy.value = true; try { const result = await api.post<Card>(`${base}/cards/${pending.value.id}/send`, undefined, 60000); if (!flag(result.sentOk)) toast(result.errorMsg || '链接发送失败，请查看发送记录', 'bad'); else toast('贺卡链接已提交企业微信'); pending.value = null; await load(); emit('sent') } catch (e) { toast(errText(e), 'bad') } finally { busy.value = false } }
onMounted(() => { void load() })
onUnmounted(() => { loadSeq++; closePreview() })
</script>
